const textFromLibraryText = (value: LibraryItemDef['def'] | LibraryItemDef['directive']): string => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  return [value.bright, value.dark, value.tension].filter(Boolean).join(' / ');
};

