const withCreatureAxisDefaults = (blockId: string, items: LibraryItemDef[]) => {
  const patch = creatureAxisDefaultsByBlock[blockId] || {};
  return items.map(item => ({
    ...patch,
    ...item,
    compatibleEras: [...new Set([...(patch.compatibleEras || []), ...(item.compatibleEras || []), ...(item.eras || [])])],
    realityTags: [...new Set([...(patch.realityTags || []), ...(item.realityTags || [])])],
    tags: [...new Set([...(patch.tags || []), ...(item.tags || [])])]
  }));
};

